          "audioUrl": "/audio/jlpt/n5-2013-07/q07.mp3",
          "transcript": "女の人がバス会社の人と話しています。女の人はどのバスに乗りますか。\n女「すみません、山川駅へ行きたいんですが、何番のバスですか。」\n男「山川駅ですね。１番と２番ですが、２番のほうが速いですよ。」\n女「じゃあ、２番に乗ります。」\n質問：女の人はどのバスに乗りますか。",
