          "audioUrl": "/audio/jlpt/n5-2024-07/q05.mp3",
          "transcript": "デパートで男の人と女の人が話しています。男の人は何階に行きますか。\n男「すみません、子供の靴はどこにありますか。」\n女「子供の靴ですね。２階と３階に靴の売り場がありますが、子供のは３階でございます。」\n男「３階ですね。ありがとうございます。」\n質問：男の人は何階に行きますか。",
