          "audioUrl": "/audio/jlpt/n5-2021-12/q05.mp3",
          "transcript": "学校で先生が話しています。学生はどこで新しい教科書を買いますか。\n女「ええ、明日から新しい教科書を使います。教科書は１階の１０１教室で売っていますから、今日の午後に買ってください。２階の事務所ではありませんよ。」\n質問：学生はどこで新しい教科書を買いますか。",
